#!/usr/bin/env python3
"""Summarize bounded paired effects and audit unchanged accepted evidence."""
import hashlib,importlib.util,json,math,pathlib,sys
sys.dont_write_bytecode=True
HERE=pathlib.Path(__file__).resolve().parent;ROOT=HERE.parents[2]
sha=lambda p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
load=lambda p:json.loads(pathlib.Path(p).read_text())
def main():
 m=load(HERE/'mathematical_verification.json');r=load(HERE/'refinement.json');patch=load(HERE/'label_patch_verification.json');review=load(HERE/'review/reduced_solver_comparison.json')
 runsha=sha(HERE/'axial_fin_numerical_run.py');current=sha(HERE/'axial_fin.py')
 assert m['axial_code_sha256']==r['axial_code_sha256']==review['code_sha256']==runsha
 assert patch['numerical_run_solver_sha256']==runsha and patch['current_solver_sha256']==current and all(patch['checks'].values())
 assert all(m['gates'].values()) and all(r['gates'].values())
 spec=importlib.util.spec_from_file_location('immutable_accepted_fin_audit',ROOT/'research/plate_fin/audit_package.py');audit=importlib.util.module_from_spec(spec);spec.loader.exec_module(audit)
 frozen=audit.audit(ROOT,expected_manifest_sha256='b56204f3ac3f6cbc7536869e5aa77f8a0cba3474297e3f0bc459a79f55f021c3')
 (HERE/'accepted_package_immutability.json').write_text(json.dumps(frozen,indent=2)+'\n')
 final=[]
 for v in [4.,10.]:
  case=next(x for x in r['rows'] if x['V_interior_m_s']==v and x['mesh']['gap_cells']==48 and x['mesh']['axial_slabs']==480)
  ax=next(x for x in r['comparisons'] if x['speed']==v and x['label']=='axial48_240_to480');tr=next(x for x in r['comparisons'] if x['speed']==v and x['label']=='transverse36_to48')
  G0=case['baseline_same_mesh_G_W_K'];G1=case['G_W_K'];delta=G1/G0-1;assert math.isclose(delta,case['paired_relative_conductance_change'],rel_tol=0,abs_tol=1e-15)
  final.append({'speed_m_s':v,'baseline_same_mesh_G_W_K':G0,'axial_conduction_G_W_K':G1,'relative_conductance_change':delta,'conductance_change_percent':100*delta,'relative_resistance_change':G0/G1-1,'resistance_change_percent':100*(G0/G1-1),'last_axial_delta_change_percentage_points':ax['absolute_delta_change_percentage_points'],'last_transverse_delta_change_percentage_points':tr['absolute_delta_change_percentage_points'],'effect_over_last_axial_change':abs(delta)/ax['absolute_delta_change'],'effect_over_last_transverse_change':abs(delta)/tr['absolute_delta_change'],'absolute_G_axial_refinement_percent':100*ax['relative_change_in_absolute_baseline_G'],'absolute_G_transverse_refinement_percent':100*tr['relative_change_in_absolute_baseline_G'],'energy_relative_balance':case['energy_relative_balance'],'true_schur_relative_residual':case['true_schur_relative_residual']})
 summary={'status':'verified_conditional_small_axial_effect_at_two_declared_probes','post_comparison_model_form_investigation':True,'physical_validation_pass':None,'aircraft_transfer_authorized':False,'experimental_residuals_recomputed':False,'original12_measurements_unchanged':True,'accepted_package_unchanged':frozen['all_passed'],'physical_change':'Only axial fin conduction0→ks, with insulated fin axial ends; vertical conduction, interface resistance, side floors, equal-flow assumption and prescribed FD velocity held fixed','primary_material_k_W_m_K':205.,'mesh':{'gap_cells':48,'height_cells':144,'axial_slabs':480,'half_domain_represents_full16_fin17_channel_array':True},'results':final,'interpretation':'Stable paired differences indicate a small conductance decrease in this defined model. Absolute-G grid changes are larger than the paired effect; do not claim equally precise absolute conductance or compare this480-slab result directly against an unmatched1600-slab reference.','uncertainty_notice':'Successive mesh differences and tolerance tests are numerical diagnostics, not confidence intervals or proven physical bounds','remaining_omissions':['hydrodynamic entrance development','fluid axial conduction','fin frontal/end-face convection','base spreading','actual material/per-run property identification','actual channel flow partition'],'numerical_quality':{'mathematical_gate_count':len(m['gates']),'all_mathematical_gates_passed':True,'all_refinement_gates_passed':True,'maximum_refinement_energy_relative_balance':max(x['energy_relative_balance'] for x in r['rows']),'maximum_case_seconds':max(x['elapsed_seconds'] for x in r['rows']),'maximum_process_peak_RSS_MiB':max(x['process_peak_RSS_MiB'] for x in r['rows']),'default_to_tighter_tolerance_pilot_absolute_delta_difference':m['pilot_tolerance_absolute_delta_difference'],'too_strict_tolerance_stress_test':'Independent reviewer retained a failed rtol1e-13 attempt; default1e-10 and attainable1e-12 results agree. Preconditioned callback residuals are not substituted for true residuals.'},'provenance':{'numerical_run_solver_sha256':runsha,'current_label_corrected_solver_sha256':current,'label_only_patch_proof_sha256':sha(HERE/'label_patch_verification.json'),'plan_sha256':sha(HERE/'PLAN.md'),'mathematical_verification_sha256':sha(HERE/'mathematical_verification.json'),'refinement_sha256':sha(HERE/'refinement.json'),'accepted_package_manifest_sha256':'b56204f3ac3f6cbc7536869e5aa77f8a0cba3474297e3f0bc459a79f55f021c3'}}
 (HERE/'study_summary.json').write_text(json.dumps(summary,indent=2)+'\n')
 lines=['# Axial fin conduction: bounded model-form result','', 'The isolated axial-solid-conduction extension produces a small conductance **decrease** at both declared probe speeds. This is conditional on the unchanged prescribed fully developed velocity, equal channel flow and insulated axial fin ends. It is not a new experimental-validation or aircraft-transfer claim.','', '| Speed | G without axial conduction, same mesh | G with axial conduction | Change in G | Change in Rth |','|---:|---:|---:|---:|---:|']
 for x in final:lines.append(f'| {x["speed_m_s"]:g}m/s | {x["baseline_same_mesh_G_W_K"]:.9f}W/K | {x["axial_conduction_G_W_K"]:.9f}W/K | {x["conductance_change_percent"]:+.6f}% | {x["resistance_change_percent"]:+.6f}% |')
 lines+=['','## What was actually resolved','', '| Speed | Last axial change in paired effect | Last transverse change in paired effect | Effect / axial change | Effect / transverse change |','|---:|---:|---:|---:|---:|']
 for x in final:lines.append(f'| {x["speed_m_s"]:g}m/s | {x["last_axial_delta_change_percentage_points"]:.8f}percentage points | {x["last_transverse_delta_change_percentage_points"]:.8f}percentage points | {x["effect_over_last_axial_change"]:.0f}× | {x["effect_over_last_transverse_change"]:.0f}× |')
 lines+=['','The loose predeclared0.05-percentage-point outer gate alone would not resolve an effect this small. The actual final mesh changes are much smaller: the effect exceeds them by roughly161–198× axially and337–616× transversely. Default-versus-tighter solver tolerance changes the paired effect by approximately1e−15 at the checked pilot, far below these mesh differences. These are numerical convergence observations, not confidence intervals or certified physical bounds.','', '**Absolute conductance is less accurate than the paired difference.** The36→48 transverse change in baseline G is about0.0255% at4m/s and0.0562% at10m/s; the240→480 axial change is about0.0496% and0.0302%, respectively. Each exceeds the small axial-conduction effect. The paired calculation controls both cases on the same grid; it does not justify mixing a480-slab axial result with the original1600-slab baseline.','', '## Physics held fixed','', 'Only the axial term in the fin equation was added: `k_s t (d²T_s/dy² + lambda_z d²T_s/dz²)` with lambda_z0 for recovery and1 for the isotropic case. Vertical conductivity, finite fin thickness/interface resistance, isothermal roots, adiabatic tips,15 heated interior floors,2 adiabatic side floors and equal per-channel mass flow remain unchanged. New axial fin end faces are insulated. No frontal/end-face convection or hydrodynamic entrance development is added.','', 'The solid unknowns are slab centers; the outgoing fluid value is the first-order upwind face state. Both cases use the same dz-weighted energy balance. Adding a conductive path to this convection-coupled system was not assumed to improve heat removal; the observed sign is verified against the independent direct system.','', '## Verification and practical feasibility','', f'- All{len(m["gates"])} mathematical checks pass, including exact zero-axial recovery, independent monolithic reference, full/half symmetry, energy, maximum principle, analytic uniform-bath fin, a nonconstant axial manufactured solution, insulated and high-k limits', '- Independent direct comparisons give relative conductance differences no larger than approximately1.1e−13 and all-field differences below1.8e−12 on the checked tiny grids', f'- Maximum energy imbalance across the refinement cases:{summary["numerical_quality"]["maximum_refinement_energy_relative_balance"]:.3g}relative', f'- Largest executed grid:48×144×480,552,960 global solid unknowns, with fluid eliminated by a forward march; peak process RSS{summary["numerical_quality"]["maximum_process_peak_RSS_MiB"]:.1f}MiB and slowest case{summary["numerical_quality"]["maximum_case_seconds"]:.1f}s', '- The95.8-million equivalent unknown estimate for the original48×144×1600 discretization refers to the **mirrored computational half-domain** representing the complete array. An explicitly unmirrored assembly would be about191.7million. Neither global matrix was assembled', '- A deliberately tighter rtol1e−13 stress test hit its iteration limit despite a tiny preconditioned callback residual; a roundoff floor was suspected, not established. The failed attempt is retained by the reviewer. The accepted default1e−10 and attainable1e−12 results agree; a tiny preconditioned callback residual was not treated as proof of convergence','', '## Scope and provenance','', 'No experimental residuals were recomputed, no known marker was selected or discarded, and no physical parameter was retuned. The twelve original measurements and the published accepted package remain byte-for-byte unchanged. This closes one defined omission at two declared synthetic probe speeds. It does not resolve inlet development, actual material/property uncertainty, end-face heat transfer or aircraft transfer.','', 'The exact source used for the full numerical run is `axial_fin_numerical_run.py`. The current `axial_fin.py` corrects only the full-array sample notice. `label_patch_verification.json` proves AST identity after replacing that one notice value, and independently checks the full/half labels. No equations, numerical operations, grids or tolerances changed. This avoids pretending that a display-only correction required or constituted another physical experiment.','', 'Small field files `fields_V04.json` and `fields_V10.json` use the explicitly labeled24×72×240 grid. They show baseline/axial temperature differences and signed axial solid heat flow, and reproduce their saved scalar conductance exactly. They are illustrative samples, not full-resolution fields and not the final scalar refinement mesh.','', 'Read `PLAN.md`, `mathematical_verification.json`, `refinement.json`, `review/`, `study_summary.json` and `accepted_package_immutability.json` for the full definitions and audit trail. All authored outputs stay in this ignored study folder.','']
 text='\n'.join(lines)
 # Improve prose spacing without changing hashes, code spans, or numbers.
 import re
 chunks=re.split(r'(`[^`]*`)',text)
 for i,s in enumerate(chunks):
  if not s.startswith('`'):chunks[i]=re.sub(r'(?<=[A-Za-z])(?=\d)',' ',s)
 (HERE/'RESULTS.md').write_text(''.join(chunks))
 print(json.dumps(summary,indent=2));assert all(p.stat().st_size<100000 for p in HERE.rglob('*.json'))
if __name__=='__main__':main()
